fn refused(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn business(value:&str,maximum:usize)->bool{let mut count=0;let mut text=false;for character in value.chars(){count+=1;if count>maximum{return false}text|=!character.is_whitespace();}text}
fn node_locked(node:&RasterLayerNode)->bool{match node{RasterLayerNode::Pixel{locked,..}|RasterLayerNode::Group{locked,..}|RasterLayerNode::Adjustment{locked,..}=>*locked}}
fn reference(node:&RasterLayerNode,slot:usize)->Option<&str>{if slot==0{match node{RasterLayerNode::Pixel{image_key,..}=>image_key.as_deref(),_=>None}}else{match node{RasterLayerNode::Pixel{mask,..}|RasterLayerNode::Group{mask,..}=>mask.as_ref().and_then(|mask|mask.image_key.as_deref()),_=>None}}}
fn copy(source:&str,target:&mut String,body:usize,work:&mut RetainedWorkLedger)->Result<bool,ValueError>{if source.len()>semio_s_artifact_raster_raster_model::RASTER_OWNED_FIELD_BYTES{return Err(refused("raster.bake-owned-field-budget"))}if !work.reserve_string(target,source.len()).map_err(refused)?{return Ok(false)}let start=target.len();if start==source.len(){return Ok(true)}let mut end=(start+body.min(32768)).min(source.len());while end>start&&!source.is_char_boundary(end){end-=1}if end==start{work.require_absolute(RetirementDemand{copy_bytes:source[start..].chars().next().unwrap().len_utf8(),depth:1,..Default::default()});return Ok(false)}if !work.string_push(target,&source[start..end]).map_err(refused)?{return Ok(false)}Ok(end==source.len())}
fn compare(left:&str,right:&str,offset:&mut usize,body:usize,work:&mut RetainedWorkLedger)->Result<Option<bool>,ValueError>{if left.len()!=right.len(){return Ok(Some(false))}let count=(left.len()-*offset).min(body.min(32768)/2);if count==0&&*offset<left.len(){work.require_absolute(RetirementDemand{copy_bytes:2,depth:1,..Default::default()});return Ok(None)}if !work.copy_bytes(count*2){return Ok(None)}let equal=left.as_bytes()[*offset..*offset+count]==right.as_bytes()[*offset..*offset+count];*offset+=count;Ok(if !equal{Some(false)}else if *offset==left.len(){Some(true)}else{None})}

#[derive(semio_framework_value::RetireOwned)]
struct Plan{path:[usize;33],selected:[usize;33],depth:usize,selected_depth:usize,start:usize,count:usize,nodes:usize,offset:usize,slot:usize,asset:usize,selected_refs:[bool;64],outside_refs:[bool;64]}
impl Default for Plan{fn default()->Self{Self{path:[0;33],selected:[0;33],depth:0,selected_depth:0,start:0,count:0,nodes:0,offset:0,slot:0,asset:0,selected_refs:[false;64],outside_refs:[false;64]}}}
impl Plan{
    fn siblings<'a>(&self,document:&'a RasterSnapshot)->Result<&'a[RasterLayerNode],ValueError>{let mut layers=document.layers.as_slice();for depth in 0..self.depth{let Some(RasterLayerNode::Group{children,..})=layers.get(self.path[depth])else{return Err(refused("raster.bake-source-path-changed"))};layers=children;}Ok(layers)}
    fn roots<'a>(&self,document:&'a RasterSnapshot)->Result<&'a[RasterLayerNode],ValueError>{let mut layers=document.layers.as_slice();for depth in 0..self.selected_depth{let Some(RasterLayerNode::Group{children,..})=layers.get(self.selected[depth])else{return Err(refused("raster.bake-selection-path-changed"))};layers=children;}layers.get(self.start..self.start+self.count).ok_or_else(||refused("raster.bake-selection-range-changed"))}
    fn parent<'a>(&self,document:&'a RasterSnapshot)->Result<Option<&'a RasterLayerNode>,ValueError>{if self.selected_depth==0{return Ok(None)}let mut layers=document.layers.as_slice();for depth in 0..self.selected_depth{let node=layers.get(self.selected[depth]).ok_or_else(||refused("raster.bake-parent-path-changed"))?;if depth+1==self.selected_depth{return Ok(Some(node))}let RasterLayerNode::Group{children,..}=node else{return Err(refused("raster.bake-parent-path-changed"))};layers=children;}Err(refused("raster.bake-parent-path-changed"))}
    fn inside(&self)->bool{self.depth>=self.selected_depth&&self.path[..self.selected_depth]==self.selected[..self.selected_depth]&&(self.start..self.start+self.count).contains(&self.path[self.selected_depth])}
    fn next(&mut self,document:&RasterSnapshot)->Result<bool,ValueError>{let siblings=self.siblings(document)?;if self.path[self.depth]>=siblings.len(){if self.depth==0{return Ok(true)}self.depth-=1;self.path[self.depth]+=1;return Ok(false)}let layer=&siblings[self.path[self.depth]];if let RasterLayerNode::Group{children,..}=layer{if !children.is_empty(){if self.depth==32{return Err(refused("raster.bake-depth-budget"))}self.depth+=1;self.path[self.depth]=0;return Ok(false)}}self.path[self.depth]+=1;Ok(false)}
    fn reset(&mut self){self.path=[0;33];self.depth=0;self.nodes=0;self.slot=0;self.asset=0;self.offset=0;}
}

#[derive(semio_framework_value::RetireOwned)]
#[value(send_only)]
struct Data{plan:Plan,raw:Option<RasterStackResult>,image:Option<SemioImageSnapshot>,payload:Option<RasterImagePayload>,layer:Option<RasterLayerNode>,boxed_layer:Option<Box<RasterLayerNode>>,mutations:Vec<RasterMutation>,pending_mutation:Option<RasterMutation>,scratch:String,key:String,parent:Option<String>,origin:[f64;2],width:u32,height:u32,digest:[u8;8],phase:u8,cursor:usize,destination:usize,reuse:bool,release:[bool;64],release_count:usize}
